create or replace view LDL_DATA_PRODUCTION.META.V_DV_REAL_ESTATE_EMAIL_ADDRESS_CONSISTENT(
	REAL_ESTATE_SID,
	DWH_VALID_FROM_TMSP,
	DWH_VALID_TO_TMSP,
	DWH_VALID_FG,
	REAL_ESTATE_NR,
	REAL_ESTATE_NAME,
	REAL_ESTATE_TYPE_CD,
	REAL_ESTATE_TYPE_DESCR,
	REAL_ESTATE_STATUS_CD,
	REAL_ESTATE_STATUS_DESCR,
	INT_ORG_SID,
	CURR_INT_ORG_NR,
	INT_ORG_NAME,
	INT_ORG_TYPE_CD,
	INT_ORG_TYPE_DESCR,
	OWNERSHIP_TYPE_CD,
	OWNERSHIP_TYPE_DESCR,
	OWNERSHIP_RATIO_TYPE_CD,
	OWNERSHIP_RATIO_TYPE_DESCR,
	OWN_ACQUISITION_FG,
	REAL_ESTATE_USG_TYPE_CD,
	REAL_ESTATE_USG_TYPE_DESCR,
	REPLACEMENT_REAL_ESTATE_SID,
	REPLACEMENT_REAL_ESTATE_NR,
	REPLACEMENT_REAL_ESTATE_NAME,
	REAL_ESTATE_REPLACEMENT_TYPE_CD,
	REAL_ESTATE_REPLACEMENT_TYPE_DESCR,
	WH_BUILDING_TYPE_CD,
	WH_BUILDING_TYPE_DESCR,
	WH_PURPOSE_CD,
	WH_PURPOSE_DESCR,
	SHARED_USG_FG,
	ISO_COUNTRY_CD,
	COUNTRY_NAME,
	CITY_NAME,
	DISTRICT_NAME,
	ZIP,
	STREET_NAME,
	HOUSE_NR,
	LON,
	LAT,
	PO_BOX_NR,
	PHONE_NR,
	FAX_NR,
	EMAIL_ADDR_TXT,
	REPORTING_COUNTRY_CD,
	REPORTING_COUNTRY_NAME,
	SALES_AREA_MEAS,
	STORAGE_AREA_MEAS,
	TOTAL_SUBLET_AREA_MEAS,
	RENTED_SUBLET_AREA_MEAS,
	UOM_CD,
	SALES_AREA_M2_MEAS,
	STORAGE_AREA_M2_MEAS,
	TOTAL_SUBLET_AREA_M2_MEAS,
	RENTED_SUBLET_AREA_M2_MEAS,
	TOTAL_PARKING_SPACE_CNT,
	OWN_PARKING_SPACE_CNT,
	UNDERGROUND_PARKING_SPACE_CNT,
	RENTAL_COST_VAL,
	RENTAL_INCOME_VAL,
	CURR_CD,
	RENTAL_COST_EUR_VAL,
	RENTAL_INCOME_EUR_VAL,
	DWH_CREATED_TMSP,
	DWH_UPDATED_TMSP,
	DWH_LOAD_ID,
	DWH_NODE_CD,
	REAL_ESTATE_ADDRESS_REAL_ESTATE_SID,
	REAL_ESTATE_ADDRESS_ADDR_SID,
	EMAIL_ADDRESS_EMAIL_ADDR_SID,
	EMAIL_ADDRESS_EMAIL_ADDR_TXT,
	FAILED_EMAIL_ADDRESS_CONSISTENT,
	TOTAL
) COMMENT='Check consistency between the email address fields in core_dim.t_dim_real_estate and core_rel.t_email_address\ninput datasets:\ncore_dim.t_dim_real_estate\ncore_rel.t_real_estate_address\ncore_rel.t_email_address'
 as SELECT real_estate.real_estate_sid, real_estate.dwh_valid_from_tmsp, real_estate.dwh_valid_to_tmsp, real_estate.dwh_valid_fg, real_estate.real_estate_nr, real_estate.real_estate_name, real_estate.real_estate_type_cd, real_estate.real_estate_type_descr, real_estate.real_estate_status_cd, real_estate.real_estate_status_descr, real_estate.int_org_sid, real_estate.curr_int_org_nr, real_estate.int_org_name, real_estate.int_org_type_cd, real_estate.int_org_type_descr, real_estate.ownership_type_cd, real_estate.ownership_type_descr, real_estate.ownership_ratio_type_cd, real_estate.ownership_ratio_type_descr, real_estate.own_acquisition_fg, real_estate.real_estate_usg_type_cd, real_estate.real_estate_usg_type_descr, real_estate.replacement_real_estate_sid, real_estate.replacement_real_estate_nr, real_estate.replacement_real_estate_name, real_estate.real_estate_replacement_type_cd, real_estate.real_estate_replacement_type_descr, real_estate.wh_building_type_cd, real_estate.wh_building_type_descr, real_estate.wh_purpose_cd, real_estate.wh_purpose_descr, real_estate.shared_usg_fg, real_estate.iso_country_cd, real_estate.country_name, real_estate.city_name, real_estate.district_name, real_estate.zip, real_estate.street_name, real_estate.house_nr, real_estate.lon, real_estate.lat, real_estate.po_box_nr, real_estate.phone_nr, real_estate.fax_nr, real_estate.email_addr_txt, real_estate.reporting_country_cd, real_estate.reporting_country_name, real_estate.sales_area_meas, real_estate.storage_area_meas, real_estate.total_sublet_area_meas, real_estate.rented_sublet_area_meas, real_estate.uom_cd, real_estate.sales_area_m2_meas, real_estate.storage_area_m2_meas, real_estate.total_sublet_area_m2_meas, real_estate.rented_sublet_area_m2_meas, real_estate.total_parking_space_cnt, real_estate.own_parking_space_cnt, real_estate.underground_parking_space_cnt, real_estate.rental_cost_val, real_estate.rental_income_val, real_estate.curr_cd, real_estate.rental_cost_eur_val, real_estate.rental_income_eur_val, real_estate.dwh_created_tmsp, real_estate.dwh_updated_tmsp, real_estate.dwh_load_id, real_estate.dwh_node_cd, real_estate_address.real_estate_sid as real_estate_address_real_estate_sid, real_estate_address.addr_sid as real_estate_address_addr_sid, email_address.email_addr_sid as email_address_email_addr_sid, email_address.email_addr_txt as email_address_email_addr_txt, CASE WHEN real_estate.email_addr_txt <> email_address_email_addr_txt THEN 1 ELSE 0 END AS FAILED_EMAIL_ADDRESS_CONSISTENT, 1 AS TOTAL FROM CORE_DIM.T_DIM_REAL_ESTATE real_estate LEFT JOIN ( SELECT real_estate_sid, addr_sid FROM CORE_REL.T_REAL_ESTATE_ADDRESS WHERE addr_type_cd = 'EMAIL' AND dwh_valid_fg = true ) real_estate_address on real_estate.real_estate_sid = real_estate_address.real_estate_sid LEFT JOIN ( SELECT email_addr_sid, email_addr_txt FROM CORE_REL.T_EMAIL_ADDRESS WHERE dwh_valid_fg = true ) email_address on real_estate_address.addr_sid = email_address.email_addr_sid WHERE real_estate.dwh_valid_fg = true;